"""Verify generated bytes, inventory and equality; never execute business rules."""

import argparse
import json
import sys
from pathlib import Path, PurePosixPath

from scripts.synthetic_generator import sha256


def inspect_dataset(directory):
    directory = Path(directory).resolve(strict=True)
    files = {}
    for path in directory.rglob("*"):
        if path.is_symlink():
            raise ValueError("Dataset must not contain symbolic links")
        if path.is_file():
            files[path.relative_to(directory).as_posix()] = path.read_bytes()
    manifest = json.loads(files["manifest.json"])
    listed = manifest["files"]
    if set(listed) != set(files) - {"manifest.json", "SHA256SUMS"}:
        raise ValueError("Manifest inventory differs from actual files")
    for name, metadata in listed.items():
        if PurePosixPath(name).is_absolute() or ".." in PurePosixPath(name).parts:
            raise ValueError("Invalid manifest path")
        if metadata != {"sha256": sha256(files[name]), "bytes": len(files[name])}:
            raise ValueError("Manifest checksum or size mismatch")
    checks = {}
    for line in files["SHA256SUMS"].decode("utf-8").splitlines():
        digest, name = line.split("  ", 1)
        if name in checks:
            raise ValueError("Duplicate checksum entry")
        checks[name] = digest
    if set(checks) != set(files) - {"SHA256SUMS"}:
        raise ValueError("Checksum inventory differs from actual files")
    if any(digest != sha256(files[name]) for name, digest in checks.items()):
        raise ValueError("Checksum mismatch")
    for name, count in manifest["counts"].items():
        if count != len(files[name].splitlines()):
            raise ValueError("Manifest record count mismatch")
    return files, manifest


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("directory", type=Path)
    parser.add_argument("--compare", type=Path)
    args = parser.parse_args()
    files, manifest = inspect_dataset(args.directory)
    print("Inventory, counts and SHA256 checks: PASS")
    print("Configuration:", json.dumps(manifest["configuration"], sort_keys=True))
    print("Record counts:", json.dumps(manifest["counts"], sort_keys=True))
    print("SHA256SUMS SHA256:", sha256(files["SHA256SUMS"]))
    if args.compare is not None:
        other, _ = inspect_dataset(args.compare)
        if files != other:
            raise ValueError("Datasets are not byte-identical")
        print("Same files, bytes and hashes: PASS")
    print("Business outcomes remain EXPECTED, not executed")


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(f"Synthetic verification: FAIL ({type(error).__name__})")
        sys.exit(1)
